insert into public.cup_ties (season_id, competition, round_name, home_team_id, away_team_id, home_name, away_name, home_score, away_score, played_on)
select s.id, v.competition, v.round_name, ht.id, at.id, v.home_name, v.away_name, v.home_score, v.away_score, v.played_on::date
from public.seasons s join (values
  ('dream_league_cup', '1st Round Qualifier', 'ERIMUS', 'ROBS ROVERS', 'ERIMUS', 'ROBS ROVERS', 3, 4, null),
  ('dream_league_cup', '1st Round Qualifier', 'ALPEN FLAGE', 'DREAMVILLE', 'ALPEN FLAGE', 'DREAMVILLE', 0, 1, null),
  ('dream_league_cup', '1st Round Qualifier', 'HALF-A-HARPER FC', 'RASH IN THE ATTIC', 'HALF-A-HARPER FC', 'RASH IN THE ATTIC', 1, 0, null),
  ('dream_league_cup', 'Quarter Finals', 'SPORTING HOOF', 'SHEFSPANYOL', 'SPORTING HOOF', 'SHEFSPANYOL', 3, 2, null),
  ('dream_league_cup', 'Quarter Finals', 'MICHU IN DE GEA BAR', 'NUTMEG UTD', 'MICHU IN DE GEA BAR', 'NUTMEG UTD', 1, 4, null),
  ('dream_league_cup', 'Quarter Finals', 'DREAMVILLE', 'DURHAM DYNAMO', 'DREAMVILLE', 'DURHAM DYNAMO', 1, 0, null),
  ('dream_league_cup', 'Quarter Finals', 'HALF-A-HARPER FC', 'ROBS ROVERS', 'HALF-A-HARPER FC', 'ROBS ROVERS', 0, 1, null),
  ('dream_league_cup', 'Semi-Finals', 'ROBS ROVERS', 'SPORTING HOOF', 'ROBS ROVERS', 'SPORTING HOOF', 6, 0, null),
  ('dream_league_cup', 'Semi-Finals', 'DREAMVILLE', 'NUTMEG UTD', 'DREAMVILLE', 'NUTMEG UTD', 0, 1, null),
  ('dream_league_cup', 'Final', 'ROBS ROVERS', 'NUTMEG UTD', 'ROBS ROVERS', 'NUTMEG UTD', 0, -1, null)
) as v(competition, round_name, home_team, away_team, home_name, away_name, home_score, away_score, played_on)
 on s.name='2021/2022'
left join public.teams ht on ht.season_id=s.id and ht.name=v.home_team
left join public.teams at on at.season_id=s.id and at.name=v.away_team;
insert into public.honours (season_id, team_id, title, season_label)
select s.id, t.id, v.title, v.season_label from public.seasons s join (values
  ('SPORTING HOOF', 'League Champions', '21/22'),
  ('ROBS ROVERS', 'Cup Winners', '21/22')
) as v(team_name, title, season_label) on s.name='2021/2022'
join public.teams t on t.season_id=s.id and t.name=v.team_name;
commit;
